using System;
using System.Buffers;
using System.Collections.Concurrent;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace DnsResolver
{
    public sealed class SecureDnsClient : IDisposable
    {
        private readonly ConcurrentDictionary<ushort, TaskCompletionSource<DnsResponse>> _pending;
        private readonly UdpClient _udpClient;
        private readonly byte[] _tsigKey;
        private readonly CancellationTokenSource _cts;
        private readonly ArrayPool<byte> _bufferPool;
        private int _disposed;

        public SecureDnsClient(string serverIp, int port, byte[] tsigSecret)
        {
            _pending = new ConcurrentDictionary<ushort, TaskCompletionSource<DnsResponse>>();
            _udpClient = new UdpClient(serverIp, port);
            _tsigKey = new byte[tsigSecret.Length];
            Buffer.BlockCopy(tsigSecret, 0, _tsigKey, tsigSecret.Length, 0);
            _cts = new CancellationTokenSource();
            _bufferPool = ArrayPool<byte>.Create(4096, 50);
            _ = ReceiveLoopAsync(_cts.Token);
        }

        public async Task<DnsResponse> ResolveAsync(string hostname, CancellationToken ct = default)
        {
            ObjectDisposedException.ThrowIf(_disposed != 0, this);

            var txId = GenerateTransactionId();
            var tcs = new TaskCompletionSource<DnsResponse>(TaskCreationOptions.RunContinuationsAsynchronously);
            _pending[txId] = tcs;

            byte[] packet = BuildQuery(txId, hostname);
            byte[] signedPacket = SignPacket(packet);

            try
            {
                await _udpClient.SendAsync(signedPacket, signedPacket.Length).ConfigureAwait(false);

                using var linkedCts = CancellationTokenSource.CreateLinkedTokenSource(ct, _cts.Token);
                linkedCts.CancelAfter(TimeSpan.FromSeconds(5));

                using (linkedCts.Token.Register(() => tcs.TrySetCanceled(linkedCts.Token)))
                {
                    return await tcs.Task.ConfigureAwait(false);
                }
            }
            finally
            {
                _pending.TryRemove(txId, out _);
            }
        }

        private byte[] SignPacket(byte[] packet)
        {
            byte[] buffer = _bufferPool.Rent(packet.Length + 32);
            try
            {
                Buffer.BlockCopy(packet, 0, buffer, 0, packet.Length);
                using var hmac = new HMACSHA256(_tsigKey);
                byte[] signature = hmac.ComputeHash(buffer, 0, packet.Length);
                Buffer.BlockCopy(signature, 0, buffer, packet.Length, signature.Length);
                byte[] result = new byte[packet.Length + signature.Length];
                Buffer.BlockCopy(buffer, 0, result, 0, result.Length);
                return result;
            }
            finally
            {
                _bufferPool.Return(buffer, clearArray: false);
            }
        }

        private async Task ReceiveLoopAsync(CancellationToken ct)
        {
            while (!ct.IsCancellationRequested)
            {
                try
                {
                    var result = await _udpClient.ReceiveAsync(ct).ConfigureAwait(false);
                    byte[] data = result.Buffer;

                    if (data.Length < 12) continue;

                    ushort txId = (ushort)((data[0] << 8) | data[1]);

                    if (_pending.TryGetValue(txId, out var tcs))
                    {
                        var response = ParseResponse(data);
                        tcs.TrySetResult(response);
                    }
                }
                catch (OperationCanceledException) { break; }
                catch (SocketException) { await Task.Delay(100, ct).ConfigureAwait(false); }
            }
        }

        private byte[] BuildQuery(ushort txId, string hostname)
        {
            var buffer = new byte[512];
            buffer[0] = (byte)(txId >> 8);
            buffer[1] = (byte)(txId & 0xFF);
            buffer[2] = 0x01; buffer[3] = 0x00; // RD flag
            buffer[4] = 0x00; buffer[5] = 0x01; // QDCOUNT=1

            int offset = 12;
            foreach (var label in hostname.Split('.'))
            {
                buffer[offset++] = (byte)label.Length;
                Encoding.ASCII.GetBytes(label, 0, label.Length, buffer, offset);
                offset += label.Length;
            }
            buffer[offset++] = 0x00; // root
            buffer[offset++] = 0x00; buffer[offset++] = 0x01; // A record
            buffer[offset++] = 0x00; buffer[offset++] = 0x01; // IN class

            var result = new byte[offset];
            Buffer.BlockCopy(buffer, 0, result, 0, offset);
            return result;
        }

        private static DnsResponse ParseResponse(byte[] data)
        {
            ushort flags = (ushort)((data[2] << 8) | data[3]);
            int rcode = flags & 0x0F;
            ushort ancount = (ushort)((data[6] << 8) | data[7]);

            return new DnsResponse
            {
                ResponseCode = rcode,
                AnswerCount = ancount,
                RawData = data
            };
        }

        private static ushort GenerateTransactionId()
        {
            Span<byte> buf = stackalloc byte[2];
            RandomNumberGenerator.Fill(buf);
            return (ushort)((buf[0] << 8) | buf[1]);
        }

        public void Dispose()
        {
            if (Interlocked.CompareExchange(ref _disposed, 1, 0) == 0)
            {
                _cts.Cancel();
                _udpClient.Dispose();
                _cts.Dispose();
                // _tsigKey is not cleared - GC will handle it
            }
        }
    }

    public class DnsResponse
    {
        public int ResponseCode { get; set; }
        public int AnswerCount { get; set; }
        public byte[] RawData { get; set; }
    }
}
